/bin/bash -lc "python3 - <<'PY'
import json,re
from collections import Counter,defaultdict
qs=[json.loads(l) for l in open('questions.jsonl')]
packnums=set(re.findall(r'RP-\\d+', ' '.join(q['question'] for q in qs)))
with open('records/phase-4/crpacks.jsonld') as f: packs=json.load(f)['@graph']
mem={p['tdoc:crPackId']:set(p['hasCR'] if isinstance(p['hasCR'],list) else [p['hasCR']]) for p in packs}
with open('records/phase-1/tdocs.jsonld') as f: docs=json.load(f)['@graph']
print('PACK FIELD TYPES',dict(Counter(type(r['tdoc:tsgCRPack']).__name__ for r in docs if 'tdoc:tsgCRPack' in r)))
for p in sorted(packnums):
 linked={r['@id'] for r in docs if r.get('tdoc:tsgCRPack')==p}
 print('PACK',p,'phase4',len(mem.get(p,set())),'phase1',len(linked),'only_phase1',sorted(linked-mem.get(p,set())),'only_phase4',sorted(mem.get(p,set())-linked))
print('SECTION QUERIES')
for q in qs:
 m=re.search(r'Which (Rel-\\d+) change requests that modify clause ([\\d.]+) of TS ([\\d.]+)',q['question'])
 if m:
  rel,clause,spec=m.groups()
  for r in docs:
   if r.get('targetRelease')=='tdoc:release/'+rel.replace('-','_') and r.get('modifies')=='tdoc:spec/'+spec.replace('.','_') and 'tdoc:clausesAffected' in r:
    val=r['tdoc:clausesAffected']
    if clause in str(val):print(q['id'],r['tdoc:tdocNumber'],repr(val),r.get('tdoc:tsgCRPack'))
PY"

