/bin/bash -lc "python3 - <<'PY'
import json,re
qs=[json.loads(l) for l in open('questions.jsonl')]
with open('records/phase-4/section_extensions.jsonld') as f: sections=json.load(f)['@graph']
for q in qs:
 m=re.search(r'Which (Rel-\\d+) change requests that modify clause ([\\d.]+) of TS ([\\d.]+)',q['question'])
 if m:
  rel,clause,spec=m.groups()
  prefix=f'tdoc:section/{spec}-{rel}-{clause}.'
  print('DESCENDANT SECTIONS',q['id'],[r['@id'] for r in sections if r['@id'].startswith(prefix)])
with open('records/phase-4/crpacks.jsonld') as f: packs=json.load(f)['@graph']
packmembers={r['@id']:set(r['hasCR'] if isinstance(r['hasCR'],list) else [r['hasCR']]) for r in packs}
with open('records/phase-4/cr_extensions.jsonld') as f: extensions=json.load(f)['@graph']
differences=[]
for r in extensions:
 ps=r['belongsToCRPack'] if isinstance(r['belongsToCRPack'],list) else [r['belongsToCRPack']]
 for p in ps:
  if r['@id'] not in packmembers.get(p,set()): differences.append([r['@id'],p])
print('CR-SIDE PACK LINKS MISSING FROM PACK MEMBERS',differences)
with open('records/phase-1/meetings.jsonld') as f: meetings=json.load(f)['@graph']
print('NONCANONICAL MEETING NAMES',[[r['tdoc:meetingNumber'],r['tdoc:canonicalMeetingNumber']] for r in meetings if r['tdoc:meetingNumber']"'!=r['"'tdoc:canonicalMeetingNumber']])
with open('records/phase-2/resolutions_agreements.jsonld') as f: events=json.load(f)['@graph']
for r in events:
 if r['@id'] in ['tdoc:resolution/AGR-122b-7-011','tdoc:resolution/AGR-122b-7-012','tdoc:resolution/AGR-122b-7-016','tdoc:resolution/AGR-122b-7-013','tdoc:resolution/AGR-122b-7-017']:
  print('122b AGREEMENT',r['resolutionId'],r['madeAt'],repr(r['content']))
with open('records/phase-2/resolutions_document_dispositions.jsonld') as f: events=json.load(f)['@graph']
for r in events:
 if r['@id'] in ['tdoc:resolution/DOC-122b-R1-2508143-t4451-r4','tdoc:resolution/DOC-122b-R1-2508143-b597']:
  print('122b DOCUMENT EVENT',r['resolutionId'],repr(r['content']))
PY"

